import random
import re

_MAX_N = 300_000
_MAX_VALUE = 1_000_000_000
_INTEGER = r"[+-]?[0-9]+"


def _bounded_integer(token: str, magnitude_limit: int) -> int | None:
    if re.fullmatch(_INTEGER, token) is None:
        return None
    negative = token.startswith("-")
    digits = token[1:] if token[0] in "+-" else token
    digits = digits.lstrip("0") or "0"
    limit = str(magnitude_limit)
    if len(digits) > len(limit):
        return None
    if len(digits) == len(limit) and digits > limit:
        return None
    magnitude = int(digits)
    return -magnitude if negative else magnitude


def _parse_input(inp: str) -> list[int] | None:
    tokens = inp.split()
    if not tokens:
        return None
    size = _bounded_integer(tokens[0], _MAX_N)
    if size is None or size < 2 or len(tokens) != size + 1:
        return None
    values = []
    for token in tokens[1:]:
        value = _bounded_integer(token, _MAX_VALUE)
        if value is None or value < 1:
            return None
        values.append(value)
    return values


def _format_input(values: list[int]) -> str:
    return f"{len(values)}\n" + " ".join(map(str, values)) + "\n"


def validate_input(inp: str) -> bool:
    return _parse_input(inp) is not None


def gen_small(seed: int, n: int) -> list[str]:
    rng = random.Random(seed)
    cases = [
        [1, _MAX_VALUE],
        [1, 1],
        [_MAX_VALUE, 1, _MAX_VALUE],
        [1, 2, 5, 3],
        [1, 1, 1, 1, 1],
        [3, 1, 4, 1, 5, 9, 2],
        [1, 1, 1, 1, _MAX_VALUE, _MAX_VALUE, _MAX_VALUE, _MAX_VALUE],
        [_MAX_VALUE, 1, _MAX_VALUE, 1, _MAX_VALUE, 1],
        [1, 2, 3, 4, 5, 6, 7, 8],
        [1, _MAX_VALUE, _MAX_VALUE, 1, 1, _MAX_VALUE, _MAX_VALUE],
    ]
    results = [_format_input(values) for values in cases[:n]]
    for index in range(len(cases), n):
        size = rng.randint(2, 8)
        if index % 2 == 0:
            values = [rng.randint(1, 5) for _ in range(size)]
        else:
            values = [rng.randint(1, _MAX_VALUE) for _ in range(size)]
        results.append(_format_input(values))
    return results if n > 0 else []


def gen_stress(seed: int) -> list[str]:
    rng = random.Random(seed)
    even = [rng.randint(1, 10_000) for _ in range(_MAX_N // 2)]
    even.extend(
        rng.randint(_MAX_VALUE - 9_999, _MAX_VALUE)
        for _ in range(_MAX_N // 2)
    )

    odd = []
    low_run = True
    while len(odd) < _MAX_N - 1:
        length = min(rng.randint(1, 127), _MAX_N - 1 - len(odd))
        if low_run:
            odd.extend(rng.randint(1, 100_000) for _ in range(length))
        else:
            odd.extend(
                rng.randint(_MAX_VALUE - 99_999, _MAX_VALUE)
                for _ in range(length)
            )
        low_run = not low_run
    return [_format_input(even), _format_input(odd)]


def check_postconditions(inp: str, out: str) -> list[tuple[str, str]]:
    values = _parse_input(inp)
    if values is None:
        return [("POST-1", "Input violates the size, count, or value constraints.")]

    tokens = out.split()
    if len(tokens) != 1 or re.fullmatch(_INTEGER, tokens[0]) is None:
        return [("POST-3", "Expected exactly one decimal integer token.")]

    size = len(values)
    upper = (size // 2) * (max(values) - min(values))
    score = _bounded_integer(tokens[0], upper)
    if score is None or score < 0:
        return [("POST-4", f"Score must be between 0 and {upper}.")]

    lower = sum(
        abs(values[i] - values[i + 1]) for i in range(0, size - 1, 2)
    )
    if size % 2:
        leave_first = sum(
            abs(values[i] - values[i + 1]) for i in range(1, size - 1, 2)
        )
        lower = max(lower, leave_first)
    if score < lower:
        return [("POST-4", f"A legal sequence of deletions scores {lower}.")]
    return []


def metamorphic_pairs(seed: int, n: int) -> list[tuple[str, str, str, str]]:
    rng = random.Random(seed)
    pairs = []
    for index in range(n):
        size = rng.randint(2, 8)
        values = [rng.randint(1, _MAX_VALUE - 1) for _ in range(size)]
        variant = index % 4
        relation = "equal"
        if variant == 0:
            transformed = values[::-1]
        elif variant == 1:
            transformed = [_MAX_VALUE + 1 - value for value in values]
        elif variant == 2:
            offset = rng.randint(1, _MAX_VALUE - max(values))
            transformed = [value + offset for value in values]
        else:
            # The appended pair can be deleted first for zero points.
            extra = rng.randint(1, _MAX_VALUE)
            transformed = values + [extra, extra]
            relation = "le"
        pairs.append(
            ("POST-2", relation, _format_input(values), _format_input(transformed))
        )
    return pairs


def _exhaustive_score(remaining: list[int]) -> int:
    if len(remaining) <= 1:
        return 0
    return max(
        abs(remaining[i] - remaining[i + 1])
        + _exhaustive_score(remaining[:i] + remaining[i + 2:])
        for i in range(len(remaining) - 1)
    )


def reference_small(inp: str) -> str | None:
    values = _parse_input(inp)
    if values is None or len(values) > 8:
        return None
    return str(_exhaustive_score(values)) + "\n"
